def verify():
    # fail-closed: any anomaly returns False; no imports, no I/O, exact integer arithmetic
    # witness embedded; exhaustive 2^5 and 2^3 enumeration, abort on any mismatch
    edges = [(0,1),(1,2),(2,3),(3,4),(4,0)]
    dedges = [(0,1),(1,2),(2,0)]

    def indep_und(sub, es):
        s = set(sub)
        for u, v in es:
            if u in s and v in s:
                return False
        return True

    def indep_dir(sub, des):
        s = set(sub)
        for u, v in des:
            if u in s and v in s:
                return False
        return True

    def subsets(n):
        out = []
        for mask in range(1 << n):
            out.append([i for i in range(n) if (mask >> i) & 1])
        return out

    # --- C5 structural check ---
    if len(edges) != 5:
        return False
    if sorted(edges) != [(0,1),(1,2),(2,3),(3,4),(4,0)]:
        return False
    sizes = [len(sub) for sub in subsets(5) if indep_und(sub, edges)]
    if len(sizes) != 32:
        return False            # abort on mismatch: expected full 2^5 scan
    if max(sizes) != 2:
        return False            # alpha(C5) != 2
    if any(s >= 3 for s in sizes):
        return False            # size-3 forbidding, exhaustively
    wit = [0, 2]
    if len(wit) != 2 or not indep_und(wit, edges):
        return False            # witness {0,2} independent and extremal

    # --- directed 3-cycle under size-3-forbidding encoding ---
    if sorted(dedges) != [(0,1),(1,2),(2,0)]:
        return False
    dsizes = [len(sub) for sub in subsets(3) if indep_dir(sub, dedges)]
    if len(dsizes) != 8:
        return False            # abort on mismatch: expected full 2^3 scan
    if max(dsizes) != 2:
        return False            # alpha != 2 for the 3-cycle surrogate
    if any(s >= 3 for s in dsizes):
        return False            # size-3 forbidding confirmed exhaustively
    dwit = [0, 1]
    if not indep_dir(dwit, dedges) or len(dwit) != 2:
        return False
    return True

RESULT = verify()
